        customer_order_number as customer_order_number
    from {{ ref('int_fl_js_marts_enriched__exp_customer_order_num') }}
),

rtr_order_value_band__high_value as (
    -- RTR_ORDER_VALUE_BAND (Router) group HIGH_VALUE: ORDER_TOTAL >= 50
    select
        customer_id as customer_id1,
        ordered_at_day as ordered_at_day1,
        order_id as order_id1,
        location_id as location_id1,
        order_subtotal as order_subtotal1,
        order_tax_paid as order_tax_paid1,
        order_total as order_total1,
        item_lines as item_lines1,
        item_revenue as item_revenue1,
