        food_share_of_lines as food_share_of_lines1,
        drink_share_of_lines as drink_share_of_lines1,
        customer_order_number as customer_order_number1
    from srt_before_router
    where (order_total >= 50)
),

rtr_order_value_band__standard as (
    -- RTR_ORDER_VALUE_BAND (Router) group STANDARD: ORDER_TOTAL < 50
    select
        customer_id as customer_id3,
        ordered_at_day as ordered_at_day3,
        order_id as order_id3,
        location_id as location_id3,
        order_subtotal as order_subtotal3,
        order_tax_paid as order_tax_paid3,
