        customer_order_number as customer_order_number3
    from srt_before_router
    where (order_total < 50)
),

exp_high_band as (
    -- EXP_HIGH_BAND (Expression)
    select
        customer_id1 as customer_id,
        ordered_at_day1 as ordered_at_day,
        order_id1 as order_id,
        location_id1 as location_id,
        order_subtotal1 as order_subtotal,
