    from rtr_order_value_band__standard
),

un_order_bands as (
    -- UN_ORDER_BANDS (Union): UNION ALL of 2 input groups
    -- input group EXP_HIGH_BAND
    select
        order_id as order_id,
        customer_id as customer_id,
        location_id as location_id,
        ordered_at_day as ordered_at_day,
        order_subtotal as order_subtotal,
        order_tax_paid as order_tax_paid,
