        drink_share_of_lines as drink_share_of_lines,
        customer_order_number as customer_order_number,
        order_value_band as order_value_band
    from exp_high_band

    union all

    -- input group EXP_STD_BAND
    select
        order_id as order_id,
        customer_id as customer_id,
        location_id as location_id,
        ordered_at_day as ordered_at_day,
        order_subtotal as order_subtotal,
